    assign sram_buffer_axi_awvalid = descr_wr_master_256b_aw_gnt_sram_buffer || sink_wr_master_256b_aw_gnt_sram_buffer || stream_master_256b_aw_gnt_sram_buffer || cpu_master_256b_aw_gnt_sram_buffer;

