    assign ddr_controller_axi_arid = (src_rd_master_256b_ar_gnt_ddr_controller ? src_rd_master_256b_ar.id : '0) |
        (stream_master_256b_ar_gnt_ddr_controller ? stream_master_256b_ar.id : '0) |
