    assign ddr_controller_axi_bridge_id_ar = (src_rd_master_256b_ar_gnt_ddr_controller ? src_rd_master_bridge_id_ar : '0) |
        (stream_master_256b_ar_gnt_ddr_controller ? stream_master_bridge_id_ar : '0) |
