    wire cpu_master_32b_ar_to_apb_periph = ((cpu_master_32b_ar.addr >= 32'hc0000000) && (cpu_master_32b_ar.addr <= 32'hcfffffff));
    wire cpu_master_32b_ar_gnt_apb_periph = cpu_master_32b_ar_to_apb_periph;
