    logic [0:0] stream_master_256b_wdest_mem [16];
    logic [4:0] stream_master_256b_wdest_wptr, stream_master_256b_wdest_rptr;
    wire [0:0] stream_master_256b_wdest_enc = stream_master_256b_aw_to_ddr_controller ? 1'd1 : 1'd0;
